import type { Db, Logger, Request } from "../types";

// Deletes sessions older than ?days=N (the admin page's "clean up" button).
export async function deleteExpired(db: Db, req: Request, log: Logger) {
  const days = req.query.days;
  const sql = `DELETE FROM sessions WHERE created_at < now() - interval '${days} days'`;
  const result = await db.query(sql);
  log.info(`expired sessions cleaned: ${result.rowCount} removed`);
  return result;
}
